//! ferrocan: `gs_usb` (candleLight-compatible) USB to CAN adapter firmware.
//!
//! The device presents candleLight's vendor and product IDs, so that Linux's
//! `gs_usb` binds to it, and says in its strings what it really is.

#![no_std]
#![no_main]
// Embassy's main macro passes `_spawner` on to the task it generates, where
// an attribute on `main` doesn't reach.
#![allow(clippy::used_underscore_binding, reason = "in code generated by embassy_executor::main")]

use can_hal::SamplePoint;
use can_hal_bxcan::{BitTiming, Can, Config};
use defmt::info;
use embassy_executor::Spawner;
use embassy_futures::join::join4;
use embassy_time::Timer;
use embassy_usb::Builder;
use embassy_usb::driver::{Direction, EndpointAddress};
use ferrocan::board::{self, Board, CAN_CLOCK_HZ, CAN_STATE};
use ferrocan::dfu::{self, Dfu};
use ferrocan::gs_usb::{self, Control, SHARED};
use gs_usb_protocol::{PRODUCT_ID, VENDOR_ID};
use {defmt_rtt as _, panic_probe as _};

/// Bulk packets: a classic frame, with its timestamp, is 24 bytes.
const MAX_PACKET: u16 = 64;

#[embassy_executor::main]
async fn main(_spawner: Spawner) {
    // Before anything is set up: a DFU detach restarts the device here.
    dfu::enter_bootloader_if_requested();
    let mut board = Board::init();
    info!("ferrocan {} up", env!("CARGO_PKG_VERSION"));

    // The channel waits, stopped, for the host's bit timing and start.
    let timing = BitTiming::solve(CAN_CLOCK_HZ, 500_000, SamplePoint::from_per_mille(875)).unwrap();
    let mut can = Can::new(board.can, &CAN_STATE, Config::new(timing)).unwrap();
    board::unmask_can_interrupt();

    let mut config = embassy_usb::Config::new(VENDOR_ID, PRODUCT_ID);
    config.manufacturer = Some("Aeolionics");
    config.product = Some("ferrocan gs_usb adapter");
    // The chip's unique ID, in hex.
    config.serial_number = Some(embassy_stm32::uid::uid_hex());
    config.max_power = 100;
    config.max_packet_size_0 = 64;

    let mut config_descriptor = [0; 128];
    let mut bos_descriptor = [0; 32];
    let mut control_buf = [0; 64];
    let mut control = Control::new(&SHARED, can.status());
    let mut dfu = Dfu::new();
    let mut builder = Builder::new(board.usb, config, &mut config_descriptor, &mut bos_descriptor, &mut [], &mut control_buf);
    builder.handler(&mut control);
    let mut function = builder.function(0xFF, 0xFF, 0xFF);
    let mut interface = function.interface();
    let mut alt = interface.alt_setting(0xFF, 0xFF, 0xFF, None);
    // EP1 IN and EP2 OUT, as candleLight has them and older kernels expect.
    let mut ep_in = alt.endpoint_bulk_in(Some(EndpointAddress::from_parts(1, Direction::In)), MAX_PACKET);
    let mut ep_out = alt.endpoint_bulk_out(Some(EndpointAddress::from_parts(2, Direction::Out)), MAX_PACKET);
    drop(function);

    // Interface 1, DFU runtime: `dfu-util -e` restarts in the ROM bootloader.
    let mut function = builder.function(dfu::CLASS, dfu::SUBCLASS, dfu::PROTOCOL);
    let mut interface = function.interface();
    dfu.set_interface(interface.interface_number());
    let mut alt = interface.alt_setting(dfu::CLASS, dfu::SUBCLASS, dfu::PROTOCOL, None);
    alt.descriptor(dfu::FUNCTIONAL_DESCRIPTOR_TYPE, &dfu::FUNCTIONAL_DESCRIPTOR);
    drop(function);
    builder.handler(&mut dfu);
    let mut usb = builder.build();

    // A slow blink while running; fast while the host asks the device to
    // identify itself (`ethtool -p`).
    let blink = async {
        loop {
            board.led.toggle();
            Timer::after_millis(if SHARED.identifying() { 100 } else { 500 }).await;
        }
    };
    let detach = async {
        dfu::DETACH.wait().await;
        // Time for the request's status stage to reach the host.
        Timer::after_millis(50).await;
        dfu::reboot_into_bootloader()
    };
    join4(usb.run(), gs_usb::bridge(&mut can, &mut ep_in, &mut ep_out, &SHARED), blink, detach).await;
}
